}
.bubble-me-custom.first, .bubble-me-custom.mid, .bubble-me-custom.last, .bubble-me-custom.single,
.bubble-them-custom.first, .bubble-them-custom.mid, .bubble-them-custom.last, .bubble-them-custom.single {
  border-radius: 18px !important;
  border: none !important; /* 彻底断绝任何连发描边 */
}

/* --- 我方小尾巴 --- */
.bubble-me-custom::before {
  content: "" !important; position: absolute !important;
  width: 20px !important; height: 20px !important;
  bottom: 0px !important; right: -8px !important;
  background-color: var(--bubble-me-bg) !important; opacity: 1 !important;
  -webkit-mask: url("https://imgbed.heliar.top/i/kE6Uk61-NmOVnoip_IMG_5358.png") no-repeat center/contain !important;
  mask: url("https://imgbed.heliar.top/i/kE6Uk61-NmOVnoip_IMG_5358.png") no-repeat center/contain !important;
  pointer-events: none !important; z-index: -1 !important; display: none !important;
}
.bubble-me-custom.last::before, .bubble-me-custom.single::before,
.msg-bubble-wrapper.is-last .bubble-me-custom::before, .msg-bubble-wrapper.is-single .bubble-me-custom::before,
[data-last="true"] .bubble-me-custom::before { display: block !important; }
.bubble-me-custom.first::before, .bubble-me-custom.mid::before { display: none !important; }

/* --- 对方小尾巴 --- */
.bubble-them-custom::before {
  content: "" !important; position: absolute !important;
  width: 20px !important; height: 20px !important;
  bottom: 0px !important; left: -8px !important;
  background-color: var(--bubble-them-bg) !important; opacity: 1 !important;
  -webkit-mask: url("https://imgbed.heliar.top/i/kE6Uk61-NmOVnoip_IMG_5358.png") no-repeat center/contain !important;
  mask: url("https://imgbed.heliar.top/i/kE6Uk61-NmOVnoip_IMG_5358.png") no-repeat center/contain !important;
  transform: scaleX(-1) !important; pointer-events: none !important; z-index: -1 !important; display: none !important;
}
.bubble-them-custom.last::before, .bubble-them-custom.single::before,
.msg-bubble-wrapper.is-last .bubble-them-custom::before, .msg-bubble-wrapper.is-single .bubble-them-custom::before,
[data-last="true"] .bubble-them-custom::before { display: block !important; }
.bubble-them-custom.first::before, .bubble-them-custom.mid::before { display: none !important; }

/* =========================================================
   4.1 【打字状态 & 特殊卡片 彻底掐灭小尾巴 (含视频卡片最高优先级)】
   ========================================================= */
.bubble-them-custom.msg-streaming,
.bubble-them-custom:has([class*="typing"]),
.bubble-them-custom:has([class*="dot"]),
.msg-bubble-wrapper.is-streaming .bubble-them-custom,
.msg-bubble-wrapper:has([class*="typing"]) .bubble-them-custom,
.msg-bubble-wrapper:has([class*="dot"]) .bubble-them-custom,
.typing-indicator,
.typing-dots {
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  border: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  animation: none !important;
  padding: 6px 4px !important;
}

.bubble-them-custom.msg-streaming::before,
.bubble-them-custom.msg-streaming::after,
.bubble-them-custom:has([class*="typing"])::before,
.bubble-them-custom:has([class*="typing"])::after,
.bubble-them-custom:has([class*="dot"])::before,
.bubble-them-custom:has([class*="dot"])::after,
.msg-bubble-wrapper.is-streaming .bubble-them-custom::before,
.msg-bubble-wrapper.is-streaming .bubble-them-custom::after,
.msg-bubble-wrapper:has([class*="typing"]) .bubble-them-custom::before,
.msg-bubble-wrapper:has([class*="typing"]) .bubble-them-custom::after,
.msg-bubble-wrapper:has([class*="dot"]) .bubble-them-custom::before,
.msg-bubble-wrapper:has([class*="dot"]) .bubble-them-custom::after {
  display: none !important;
  content: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

/* 👇【核心修复】彻底灭杀我方/对方所有卡片上的小尾巴（含视频/通话卡片） */
.bubble-me-custom:has(.msg-transfer-card)::before,
.bubble-me-custom:has(.msg-transfer-card)::after,
.bubble-me-custom:has(.msg-redpacket-card)::before,
.bubble-me-custom:has(.msg-redpacket-card)::after,
.bubble-me-custom:has(.gift-ig-container)::before,
.bubble-me-custom:has(.gift-ig-container)::after,
.bubble-me-custom:has(.msg-sim-card)::before,
.bubble-me-custom:has(.msg-sim-card)::after,
.bubble-me-custom:has(.msg-loc-card)::before,
.bubble-me-custom:has(.msg-loc-card)::after,
.bubble-me-custom:has(.msg-videocall-card)::before,
.bubble-me-custom:has(.msg-videocall-card)::after,
.bubble-me-custom:has([class*="videocall"])::before,
.bubble-me-custom:has([class*="videocall"])::after,
.bubble-them-custom:has(.msg-transfer-card)::before,
.bubble-them-custom:has(.msg-transfer-card)::after,
.bubble-them-custom:has(.msg-redpacket-card)::before,
.bubble-them-custom:has(.msg-redpacket-card)::after,
.bubble-them-custom:has(.gift-ig-container)::before,
.bubble-them-custom:has(.gift-ig-container)::after,
.bubble-them-custom:has(.msg-sim-card)::before,
.bubble-them-custom:has(.msg-sim-card)::after,
.bubble-them-custom:has(.msg-loc-card)::before,
.bubble-them-custom:has(.msg-loc-card)::after,
.bubble-them-custom:has(.msg-videocall-card)::before,
.bubble-them-custom:has(.msg-videocall-card)::after,
.bubble-them-custom:has([class*="videocall"])::before,
.bubble-them-custom:has([class*="videocall"])::after,
.msg-bubble-wrapper:has(.msg-transfer-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-redpacket-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.gift-ig-container) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-sim-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-loc-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-videocall-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has([class*="videocall"]) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-sim-card) .bubble-them-custom::before,
.msg-bubble-wrapper:has(.msg-loc-card) .bubble-them-custom::before,
.msg-bubble-wrapper:has(.msg-videocall-card) .bubble-them-custom::before,
.msg-bubble-wrapper:has([class*="videocall"]) .bubble-them-custom::before {
  display: none !important;
  content: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}

.bubble-me-custom:has(.msg-transfer-card),
.bubble-them-custom:has(.msg-transfer-card),
.bubble-me-custom:has(.msg-redpacket-card),
.bubble-them-custom:has(.msg-redpacket-card),
.bubble-me-custom:has(.gift-ig-container),
.bubble-them-custom:has(.gift-ig-container),
.bubble-me-custom:has(.msg-sim-card),
.bubble-them-custom:has(.msg-sim-card),
.bubble-me-custom:has(.msg-loc-card),
.bubble-them-custom:has(.msg-loc-card),
.bubble-me-custom:has(.msg-videocall-card),
.bubble-them-custom:has(.msg-videocall-card),
.bubble-me-custom:has([class*="videocall"]),
.bubble-them-custom:has([class*="videocall"]) {
  background: transparent !important;
  padding: 0 !important;
  border-radius: 22px !important;
  box-shadow: none !important;
  border: none !important;
}

/* =========================================================
   4.2 【单行流线型回复条 (绝对水平居中 + 恢复日间浅灰底色)】
   ========================================================= */
.msg-reply-block {
  display: none !important;
}

/* 容器：统一基准行高，确保内部所有子项绝对垂直居中对齐 */
.msg-reply-block-detached {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important; /* 👈 绝对垂直居中对齐 */
  order: -1 !important; 
  position: relative !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  margin: 3px 0 5px 0 !important;
  padding: 0 !important;
  width: fit-content !important;
  max-width: 85% !important;
  box-sizing: border-box !important;
  gap: 6px !important;
  line-height: 20px !important;   /* 👈 与 20px 方块高度严格等高，消除基线偏差 */
  height: 20px !important;
}

/* 人名：与水平线对齐 */
.msg-reply-detached-name {
  color: var(--text-main) !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  letter-spacing: -0.2px !important;
  white-space: nowrap !important;
  display: inline-flex !important;
  align-items: center !important;
  line-height: 20px !important;
  margin: 0 !important;
  padding: 0 !important;
}
.msg-reply-detached-name::before {
  content: "Replying to " !important;
  font-weight: 700 !important;
  color: var(--text-main) !important;
