  z-index: 101 !important;
}
.input-area-custom .more-options-item-row {
  border-bottom: 1px solid var(--more-options-divider, rgba(0, 0, 0, 0.06)) !important;
  pointer-events: auto !important;
}
.input-area-custom .more-options-item-row span,
.input-area-custom .more-options-item-row svg {
  color: var(--more-options-color, #111111) !important;
  stroke: var(--more-options-color, #111111) !important;
